const uint row = threadgroup_position_in_grid.x;
const uint tid = thread_position_in_threadgroup.x;
const uint lane = thread_index_in_simdgroup;
const uint sg = simdgroup_index_in_threadgroup;
const uint base = row * H;
threadgroup float part[4];

const bool vec = (H % 4 == 0) && (H / 4 <= 1024);
half4 hv[8];
float4 wv[8];
float ss = 0.0f;

if (vec) {
    const uint V = H / 4;
    #pragma unroll
    for (uint j = 0; j < 8; j++) {
        uint i = tid + j * 128;
        if (i < V) {
            wv[j] = float4(ld4(w, i * 4));
            half4 v = ld4(x, base + i * 4) + ld4(r, base + i * 4);
            hv[j] = v;
            st4(h, base + i * 4, v);
            float4 f = float4(v);
            ss += dot(f, f);
        }
    }
} else {
    for (uint i = tid; i < H; i += 128) {
        half v = half(float(x[base + i]) + float(r[base + i]));
        h[base + i] = v;
        float f = float(v);
        ss += f * f;
    }
}

ss = simd_sum(ss);
if (lane == 0) part[sg] = ss;
threadgroup_barrier(mem_flags::mem_threadgroup);
const float tot = part[0] + part[1] + part[2] + part[3];
const float inv = rsqrt(tot / float(H) + 1e-5f);

if (vec) {
    const uint V = H / 4;
    #pragma unroll
    for (uint j = 0; j < 8; j++) {
        uint i = tid + j * 128;
        if (i < V) st4(y, base + i * 4, half4(float4(hv[j]) * inv * wv[j]));
    }
} else {
    for (uint i = tid; i < H; i += 128) {
        y[base + i] = half(float(h[base + i]) * inv * float(w[i]));
    }
}

