inline half4 ld4(const device half* p, uint i) { return *(const device half4*)(p + i); }
inline half4 ld4(const constant half* p, uint i) { return *(const constant half4*)(p + i); }
inline void st4(device half* p, uint i, half4 v) { *(device half4*)(p + i) = v; }
